mapper.select:
SELECT kb.kb_id as target_id, GROUP_CONCAT(DISTINCT t1.label) AS label, kb.primitive_name AS biz_name FROM biz_label t1 LEFT JOIN ( -- 联合出三种类型的 target_id 和对应 kb_name SELECT id AS target_id, primitive_name, id AS kb_id FROM gienrag.knowledge_base WHERE status = 1 AND primitive_name IN
#{kbName}
UNION ALL SELECT f.id AS target_id, kb.primitive_name, kb.id as kb_id FROM folder_info f JOIN gienrag.knowledge_base kb ON f.kb_id = kb.id WHERE f.status = 1 AND kb.status = 1 AND kb.primitive_name IN
#{kbName}
UNION ALL SELECT fi.id AS target_id, kb.primitive_name, kb.id as kb_id FROM knowledge_base_list fi JOIN gienrag.knowledge_base kb ON fi.kb_id = kb.id WHERE kb.status = 1 AND kb.primitive_name IN
#{kbName}
) kb ON t1.target_id = kb.target_id WHERE t1.is_del = 1 AND kb.primitive_name is not null GROUP BY kb.kb_id, kb.primitive_name

